from pathlib import Path
import json,hashlib,subprocess,os,ast
R=Path(__file__).resolve().parent;W=R.parent
v=json.loads((R/'verified-results.json').read_text());assert v['success'];assert sum(x['capture_comparisons'] for x in v['campaigns'])==5148 and sum(x['weight_hash_comparisons'] for x in v['campaigns'])==1584
